#!/usr/bin/env bash
# Regenerates src/onnx_proto.rs from proto/onnx.proto.
#
# proto/onnx.proto is onnx/onnx v1.22.0 (onnx/onnx.proto), unchanged: the ONNX
# version ONNX Runtime 1.28.0 builds with. The generated file is checked in, so
# no build needs `protoc`; only this script does, together with network access
# for `prost-build`. Run it after replacing proto/onnx.proto, then commit both.
set -euo pipefail

crate_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
workspace_dir="$(cd "$crate_dir/../.." && pwd)"
gen_dir="$workspace_dir/target/gen-onnx-proto"

command -v protoc >/dev/null || { echo "protoc not found on PATH" >&2; exit 1; }

mkdir -p "$gen_dir/src"
cat > "$gen_dir/Cargo.toml" <<'EOF'
[package]
name = "gen-onnx-proto"
version = "0.0.0"
edition = "2024"
publish = false

[workspace]

[dependencies]
# Keep the minor version equal to `prost` in crates/voidwall-ml/Cargo.toml.
prost-build = "0.14"
EOF
cat > "$gen_dir/src/main.rs" <<'EOF'
fn main() {
    let mut args = std::env::args().skip(1);
    let (proto_dir, out_dir) = (args.next().unwrap(), args.next().unwrap());
    prost_build::Config::new()
        .out_dir(&out_dir)
        // Lets a decode from a memory-mapped file borrow the weight bytes.
        .bytes([".onnx.TensorProto.raw_data"])
        .compile_protos(&[format!("{proto_dir}/onnx.proto")], &[proto_dir])
        .expect("onnx.proto compiles");
}
EOF

out_tmp="$(mktemp -d)"
trap 'rm -rf "$out_tmp"' EXIT
cargo run --quiet --manifest-path "$gen_dir/Cargo.toml" -- "$crate_dir/proto" "$out_tmp"

{
    echo "// @generated by scripts/gen-onnx-proto.sh from proto/onnx.proto (onnx v1.22.0)."
    echo "// Do not edit by hand."
    echo
    cat "$out_tmp/onnx.rs"
} > "$crate_dir/src/onnx_proto.rs"
# Format as `cargo fmt` would, so the workspace format pass leaves it unchanged.
rustfmt --edition 2024 "$crate_dir/src/onnx_proto.rs"
echo "wrote $crate_dir/src/onnx_proto.rs"
